package com.example.exampleplugin;

import java.util.List;
import java.util.Locale;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabExecutor;

public final class KitCommand implements TabExecutor {

    private static final List<String> SUBCOMMANDS = List.of("list", "give", "reload");

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 0) {
            return false; // shows usage from plugin.yml
        }
        switch (args[0].toLowerCase(Locale.ROOT)) {
            case "list" -> sender.sendMessage(Component.text("Kits: starter, pvp", NamedTextColor.GREEN));
            case "give" -> {
                if (args.length < 2) {
                    sender.sendMessage(Component.text("Usage: /kit give <name>", NamedTextColor.RED));
                    return true;
                }
                sender.sendMessage(Component.text("Giving kit " + args[1], NamedTextColor.GREEN));
            }
            case "reload" -> {
                if (!sender.hasPermission("exampleplugin.kit.reload")) {
                    sender.sendMessage(Component.text("No permission.", NamedTextColor.RED));
                    return true;
                }
                sender.sendMessage(Component.text("Config reloaded.", NamedTextColor.GREEN));
            }
            default -> sender.sendMessage(Component.text("Unknown subcommand: " + args[0], NamedTextColor.RED));
        }
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1) {
            String prefix = args[0].toLowerCase(Locale.ROOT);
            return SUBCOMMANDS.stream().filter(s -> s.startsWith(prefix)).toList();
        }
        return List.of();
    }
}

