package com.example.myplugin;

import net.kyori.adventure.text.Component;
import org.bukkit.Material;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;

public final class InteractListener implements Listener {
    @EventHandler
    public void onInteract(PlayerInteractEvent event) {
        if (event.getHand() != EquipmentSlot.HAND) return; // event fires once per hand — handle main hand only

        Action action = event.getAction();
        if (action != Action.RIGHT_CLICK_AIR && action != Action.RIGHT_CLICK_BLOCK) return;

        ItemStack item = event.getItem(); // null when the hand is empty
        if (item == null || item.getType() != Material.BLAZE_ROD) return;

        event.setCancelled(true); // stop vanilla use (placing, eating, etc.)
        event.getPlayer().sendMessage(Component.text("You used the magic wand!"));
        if (event.getClickedBlock() != null) {
            event.getPlayer().sendMessage(Component.text(
                    "Target: " + event.getClickedBlock().getType()));
        }
    }
}

