public final class DeathListener implements Listener {
    @EventHandler
    public void onDeath(PlayerDeathEvent event) {
        // Keep inventory: MUST also clear drops, or items duplicate on the ground
        event.setKeepInventory(true);
        event.getDrops().clear();

        // Keep XP: MUST also zero dropped XP
        event.setKeepLevel(true);
        event.setDroppedExp(0);

        event.deathMessage(Component.text()
                .append(event.getEntity().displayName())
                .append(Component.text(" bit the dust!", NamedTextColor.DARK_RED))
                .build());
    }
}

package com.example.myplugin;

import io.papermc.paper.chat.ChatRenderer;
import io.papermc.paper.event.player.AsyncChatEvent;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;

public final class ChatListener implements Listener {
    @EventHandler
    public void onChat(AsyncChatEvent event) {
        // FILTER: read the message as plain text (never Component#toString())
        String plain = PlainTextComponentSerializer.plainText().serialize(event.message());
        if (plain.toLowerCase().contains("badword")) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(Component.text("Watch your language!", NamedTextColor.RED));
            return;
        }

        // FORMAT: "<Name> msg" -> "Name: msg" with colors, for all viewers
        event.renderer(ChatRenderer.viewerUnaware((source, sourceDisplayName, message) ->
                Component.text()
                        .append(sourceDisplayName.color(NamedTextColor.GRAY))
                        .append(Component.text(": ", NamedTextColor.DARK_GRAY))
                        .append(message.color(NamedTextColor.WHITE))
                        .build()));
    }
}

