public final class DelayedActions {

    private final JavaPlugin plugin;

    public DelayedActions(JavaPlugin plugin) {
        this.plugin = plugin;
    }

    /** Sends a warmup message, then teleports the player to spawn 5 seconds later. */
    public BukkitTask delayedSpawnTeleport(Player player) {
        player.sendMessage(Component.text("Teleporting in 5 seconds, don't move!", NamedTextColor.YELLOW));

        return plugin.getServer().getScheduler().runTaskLater(plugin, () -> {
            if (!player.isOnline()) {
                return; // player logged out during the warmup
            }
            player.teleport(player.getWorld().getSpawnLocation());
            player.sendMessage(Component.text("Whoosh!", NamedTextColor.GREEN));
        }, 5L * 20L); // 100 ticks = 5 seconds; keep the returned task to cancel() on move
    }
}

package com.example.myplugin;

import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

public final class StatsService {

    private final JavaPlugin plugin;

    public StatsService(JavaPlugin plugin) {
        this.plugin = plugin;
    }

    public void loadAndAnnounce(Player player) {
        UUID uuid = player.getUniqueId();

        // 1) Heavy/blocking work OFF the main thread (SQL, HTTP, file IO)
        Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
            int kills = queryKillsFromDatabase(uuid); // slow blocking call — fine here

            // 2) Hop BACK to the main thread for anything touching the world/entities
            Bukkit.getScheduler().runTask(plugin, () -> {
                Player online = Bukkit.getPlayer(uuid); // re-fetch: player may have left
                if (online == null) {
                    return;
                }
                online.sendMessage(Component.text("You have " + kills + " kills!", NamedTextColor.AQUA));
                online.setLevel(kills); // entity mutation -> main thread ONLY
            });
        });
    }

    private int queryKillsFromDatabase(UUID uuid) {
        // stand-in for a blocking JDBC/HTTP call
        return 42;
    }
}

