public final class MyPlugin extends JavaPlugin {

    private String welcomeMessage;
    private int maxHomes;
    private boolean spawnProtection;
    private List<String> blockedWorlds;

    @Override
    public void onEnable() {
        // Copies config.yml from the jar to plugins/MyPlugin/config.yml (only if missing)
        saveDefaultConfig();
        loadSettings();
    }

    public void loadSettings() {
        welcomeMessage = getConfig().getString("welcome-message", "Welcome!");
        maxHomes = getConfig().getInt("max-homes", 3);
        spawnProtection = getConfig().getBoolean("spawn-protection-enabled", true);
        blockedWorlds = getConfig().getStringList("blocked-worlds"); // empty list if absent, never null
        getLogger().info("Config loaded: maxHomes=" + maxHomes + ", blockedWorlds=" + blockedWorlds);
    }

    public Component welcomeComponent() {
        return Component.text(welcomeMessage);
    }

    public boolean isWorldBlocked(String worldName) {
        return blockedWorlds.contains(worldName);
    }
}

