package com.example.myplugin;

import java.io.File;
import java.io.IOException;
import java.util.UUID;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

public final class PlayerDataStore implements Listener {

    private final JavaPlugin plugin;
    private final File file;
    private final YamlConfiguration data;

    public PlayerDataStore(JavaPlugin plugin) {
        this.plugin = plugin;
        this.file = new File(plugin.getDataFolder(), "playerdata.yml");
        this.data = YamlConfiguration.loadConfiguration(file); // empty config if file missing
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
    }

    public int getKills(UUID uuid) {
        return data.getInt("players." + uuid + ".kills", 0);
    }

    public void addKill(UUID uuid) {
        data.set("players." + uuid + ".kills", getKills(uuid) + 1); // memory only until save()
    }

    public void save() {
        try {
            plugin.getDataFolder().mkdirs(); // fresh installs have no data folder yet
            data.save(file);
        } catch (IOException e) {
            plugin.getSLF4JLogger().error("Could not save playerdata.yml", e);
        }
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent event) {
        save(); // also call save() from your plugin's onDisable()
    }
}

