import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

public final class KitCommand implements CommandExecutor {

    private static final long COOLDOWN_MILLIS = 60_000L; // 60 seconds
    private final Map<UUID, Long> lastUsed = new HashMap<>();

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage(Component.text("Players only.", NamedTextColor.RED));
            return true;
        }

        long now = System.currentTimeMillis();
        Long last = lastUsed.get(player.getUniqueId());
        if (last != null && now - last < COOLDOWN_MILLIS) {
            long secondsLeft = (COOLDOWN_MILLIS - (now - last) + 999L) / 1000L; // ceiling
            player.sendMessage(Component.text("Wait " + secondsLeft + "s before using this again.", NamedTextColor.RED));
            return true;
        }

        lastUsed.put(player.getUniqueId(), now);
        player.getInventory().addItem(new ItemStack(Material.COOKED_BEEF, 16));
        player.sendMessage(Component.text("Kit claimed!", NamedTextColor.GREEN));
        return true;
    }
}

package com.example.myplugin;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.bukkit.Bukkit;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

public final class AutoSaver {

    /** Starts a 5-minute autosave loop. Call from onEnable; cancel the returned task in onDisable. */
    public static BukkitTask start(JavaPlugin plugin, YamlConfiguration data, File target) {
        long periodTicks = 5L * 60L * 20L; // 5 minutes in ticks

        return Bukkit.getScheduler().runTaskTimer(plugin, () -> {
            // MAIN thread: snapshot the non-thread-safe YamlConfiguration to a String
            String snapshot = data.saveToString();

            // ASYNC: slow disk write off the main thread, using only the immutable snapshot
            Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
                try {
                    target.getParentFile().mkdirs();
                    Files.writeString(target.toPath(), snapshot, StandardCharsets.UTF_8);
                } catch (IOException e) {
                    plugin.getSLF4JLogger().error("Autosave failed for " + target.getName(), e);
                }
            });
        }, periodTicks, periodTicks);
    }
}

