import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

public final class MenuPlugin extends JavaPlugin implements Listener {

    @Override
    public void onEnable() {
        getServer().getPluginManager().registerEvents(this, this);
    }

    /** Call from a command executor or event to open the menu. */
    public void openShop(Player player) {
        player.openInventory(new ShopMenu().getInventory());
    }

    static final class ShopMenu implements InventoryHolder {
        private final Inventory inventory;

        ShopMenu() {
            this.inventory = Bukkit.createInventory(this, 27,
                    Component.text("Shop", NamedTextColor.DARK_PURPLE));
            ItemStack filler = new ItemStack(Material.GRAY_STAINED_GLASS_PANE);
            filler.editMeta(meta -> meta.displayName(Component.empty()));
            for (int slot = 0; slot < 27; slot++) {
                inventory.setItem(slot, filler);
            }
            ItemStack sword = new ItemStack(Material.DIAMOND_SWORD);
            sword.editMeta(meta -> meta.displayName(
                    Component.text("Buy Sword (10 diamonds)", NamedTextColor.AQUA)
                            .decoration(TextDecoration.ITALIC, false)));
            inventory.setItem(13, sword);
        }

        @Override
        public Inventory getInventory() {
            return inventory;
        }
    }

    @EventHandler
    public void onClick(InventoryClickEvent event) {
        if (!(event.getInventory().getHolder() instanceof ShopMenu)) {
            return;
        }
        event.setCancelled(true); // cancel first: also blocks shift-clicks and number-key swaps
        ItemStack clicked = event.getCurrentItem();
        if (clicked == null || clicked.getType() == Material.GRAY_STAINED_GLASS_PANE) {
            return;
        }
        Player player = (Player) event.getWhoClicked();
        if (event.getSlot() == 13) {
            player.sendMessage(Component.text("Purchased!", NamedTextColor.GREEN));
            // NEVER closeInventory() inside this event; schedule for next tick:
            getServer().getScheduler().runTask(this, player::closeInventory);
        }
    }

    @EventHandler
    public void onDrag(InventoryDragEvent event) {
        if (event.getInventory().getHolder() instanceof ShopMenu) {
            event.setCancelled(true);
        }
    }
}

