public final class ItemPayments {

    /** Returns true and removes the items if the player can pay; false otherwise. */
    public static boolean charge(Player player, Material currency, int amount) {
        if (!player.getInventory().containsAtLeast(new ItemStack(currency), amount)) {
            player.sendMessage(Component.text(
                    "You need " + amount + " " + currency.name().toLowerCase() + "!",
                    NamedTextColor.RED));
            return false;
        }
        HashMap<Integer, ItemStack> notRemoved =
                player.getInventory().removeItem(new ItemStack(currency, amount));
        return notRemoved.isEmpty();
    }
}

