import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

public final class SpawnPlugin extends JavaPlugin {

    @Override
    public void onEnable() {
        getCommand("setspawn").setExecutor((sender, command, label, args) -> {
            if (!(sender instanceof Player player)) {
                sender.sendMessage(Component.text("Players only.", NamedTextColor.RED));
                return true;
            }
            getConfig().set("spawn", player.getLocation()); // Location is ConfigurationSerializable
            saveConfig();
            player.sendMessage(Component.text("Spawn point saved.", NamedTextColor.GREEN));
            return true;
        });
        getCommand("spawn").setExecutor((sender, command, label, args) -> {
            if (!(sender instanceof Player player)) {
                sender.sendMessage(Component.text("Players only.", NamedTextColor.RED));
                return true;
            }
            Location spawn = getConfig().getLocation("spawn");
            if (spawn == null || spawn.getWorld() == null) {
                player.sendMessage(Component.text("Spawn not set. Use /setspawn first.", NamedTextColor.RED));
                return true;
            }
            // Paper: loads the target chunk async, then teleports — safe across worlds.
            player.teleportAsync(spawn).thenAccept(success -> player.sendMessage(success
                    ? Component.text("Teleported to spawn.", NamedTextColor.GREEN)
                    : Component.text("Teleport failed.", NamedTextColor.RED)));
            return true;
        });
    }
}

