public final class WorldTeleport {

    /** Sends the player to the spawn of another world, e.g. "world_nether" or "world_the_end". */
    public static void toWorld(Player player, String worldName) {
        World target = Bukkit.getWorld(worldName); // null if not loaded or misspelled
        if (target == null) {
            player.sendMessage(Component.text("World not found: " + worldName, NamedTextColor.RED));
            return;
        }
        Location destination = target.getSpawnLocation();
        player.teleportAsync(destination).thenAccept(success -> {
            if (success) {
                player.sendMessage(Component.text("Welcome to " + worldName, NamedTextColor.GREEN));
            } else {
                player.sendMessage(Component.text("Teleport was cancelled.", NamedTextColor.RED));
            }
        });
    }
}

