import org.bukkit.scoreboard.Criteria;
import org.bukkit.scoreboard.DisplaySlot;
import org.bukkit.scoreboard.Objective;
import org.bukkit.scoreboard.Scoreboard;

public final class SidebarPlugin extends JavaPlugin {

    private final Map<UUID, Scoreboard> boards = new HashMap<>();

    @Override
    public void onEnable() {
        Bukkit.getScheduler().runTaskTimer(this, () -> {
            for (Player player : Bukkit.getOnlinePlayers()) {
                updateSidebar(player);
            }
        }, 0L, 20L); // every 20 ticks = 1 second
    }

    private void updateSidebar(Player player) {
        Scoreboard board = boards.computeIfAbsent(player.getUniqueId(), id -> {
            Scoreboard sb = Bukkit.getScoreboardManager().getNewScoreboard();
            Objective obj = sb.registerNewObjective("sidebar", Criteria.DUMMY,
                    Component.text("My Server", NamedTextColor.GOLD));
            obj.setDisplaySlot(DisplaySlot.SIDEBAR);
            return sb;
        });
        Objective obj = board.getObjective("sidebar");
        for (String entry : board.getEntries()) { // wipe old lines, then rewrite
            board.resetScores(entry);
        }
        obj.getScore("Online: " + Bukkit.getOnlinePlayers().size()).setScore(2);
        obj.getScore("Health: " + (int) player.getHealth()).setScore(1);
        player.setScoreboard(board);
    }

    @Override
    public void onDisable() {
        boards.clear();
    }
}

