import org.bukkit.scheduler.BukkitRunnable;

public final class BossBarCountdown {

    /** Shows a 10-second countdown boss bar, then removes it. */
    public static void start(JavaPlugin plugin, Player player) {
        BossBar bar = BossBar.bossBar(
                Component.text("Event starts in 10s", NamedTextColor.YELLOW),
                1.0f, BossBar.Color.RED, BossBar.Overlay.NOTCHED_10);
        player.showBossBar(bar);

        new BukkitRunnable() {
            private int secondsLeft = 10;

            @Override
            public void run() {
                secondsLeft--;
                if (secondsLeft <= 0 || !player.isOnline()) {
                    player.hideBossBar(bar);
                    cancel();
                    return;
                }
                bar.progress(secondsLeft / 10.0f); // must stay within 0.0-1.0
                bar.name(Component.text("Event starts in " + secondsLeft + "s", NamedTextColor.YELLOW));
            }
        }.runTaskTimer(plugin, 20L, 20L);
    }
}

