package com.example.eco;

import java.io.File;
import java.io.IOException;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

public final class EcoPlugin extends JavaPlugin {

    private File balancesFile;
    private YamlConfiguration balances;

    @Override
    public void onEnable() {
        balancesFile = new File(getDataFolder(), "balances.yml");
        balancesFile.getParentFile().mkdirs();
        balances = YamlConfiguration.loadConfiguration(balancesFile); // empty config if file missing

        getCommand("pay").setExecutor((sender, command, label, args) -> {
            if (!(sender instanceof Player from)) {
                sender.sendMessage(Component.text("Players only.", NamedTextColor.RED));
                return true;
            }
            if (args.length != 2) {
                from.sendMessage(Component.text("Usage: /pay <player> <amount>", NamedTextColor.RED));
                return true;
            }
            Player to = Bukkit.getPlayerExact(args[0]);
            if (to == null) {
                from.sendMessage(Component.text("That player is not online.", NamedTextColor.RED));
                return true;
            }
            double amount;
            try {
                amount = Double.parseDouble(args[1]);
            } catch (NumberFormatException e) {
                from.sendMessage(Component.text("Amount must be a number.", NamedTextColor.RED));
                return true;
            }
            if (amount <= 0 || getBalance(from.getUniqueId()) < amount) {
                from.sendMessage(Component.text("Insufficient funds.", NamedTextColor.RED));
                return true;
            }
            setBalance(from.getUniqueId(), getBalance(from.getUniqueId()) - amount);
            setBalance(to.getUniqueId(), getBalance(to.getUniqueId()) + amount);
            from.sendMessage(Component.text("Sent $" + amount + " to " + to.getName(), NamedTextColor.GREEN));
            to.sendMessage(Component.text("Received $" + amount + " from " + from.getName(), NamedTextColor.GREEN));
            return true;
        });
    }

    public double getBalance(UUID id) {
        return balances.getDouble(id.toString(), 100.0); // 100 = starting balance
    }

    public void setBalance(UUID id, double value) {
        balances.set(id.toString(), value);
        save();
    }

    private void save() {
        try {
            balances.save(balancesFile);
        } catch (IOException e) {
            getSLF4JLogger().error("Could not save balances.yml", e);
        }
    }

    @Override
    public void onDisable() {
        save();
    }
}

